// Generated by Step 10
// Updated: v1.2.1 T9 九键柯尔克孜语联想引擎
// 基于 GB/T 31921-2015 数字键盘布局的 T9 输入算法
package com.example.kyrgyzkeyboard.keyboard

/**
 * T9 九键联想引擎（柯尔克孜语）。
 *
 * 键位映射（GB/T 31921-2015 标准）：
 * 1: . ، ؛ ؟ !
 * 2: ا ب چ ع
 * 3: د ە ئ ف
 * 4: غ ح ى
 * 5: ج ك ل
 * 6: م ن و ڭ
 * 7: پ ق ر س
 * 8: ت ۇ ۅ ۉ
 * 9: ۋ ش ي ز
 * 0: 空格 ـ … « »
 *
 * 算法：数字序列 -> 字母组合匹配 -> 按词频排序
 */
object T9Engine {

    /**
     * T9 键位映射表（数字 -> 该键上的所有字母）。
     */
    private val keyToLetters: Map<Char, List<Char>> = mapOf(
        '2' to listOf('ا', 'ب', 'چ', 'ع'),
        '3' to listOf('د', 'ە', 'ئ', 'ف'),
        '4' to listOf('غ', 'ح', 'ى'),
        '5' to listOf('ج', 'ك', 'ل'),
        '6' to listOf('م', 'ن', 'و', 'ڭ'),
        '7' to listOf('پ', 'ق', 'ر', 'س'),
        '8' to listOf('ت', 'ۇ', 'ۅ', 'ۉ'),
        '9' to listOf('ۋ', 'ش', 'ي', 'ز'),
    )

    /**
     * 柯尔克孜语常用词典（基础词汇）。
     * 后续可以扩展到 GB/T 32408-2015 的 1335 个标准术语。
     */
    private val dictionary = listOf(
        // 常见 2 字母词
        "ار", "ال", "ان", "ام", "او", "اي",
        // 常见 3 字母词
        "بار", "مال", "دان", "كىم", "سەن", "مەن",
        // 常见 4 字母词
        "جالما", "باراق", "دانە", "كىرگز",
        // GB/T 32408-2015 信息技术术语（部分）
        "كومپيوتر", "داتا", "پرگرامما", "سسيتىما",
        "تور", "بазا", "فایل", "دوسكا", "مۇر",
        "اقىت", "قار", "سۇ", "تالا", "كال",
        "چي", "زىمان", "راس", "پا", "مە",
        "ەر", "ەل", "ەك", "ەم", "ەن"
    )

    /**
     * 根据数字序列获取 T9 候选词。
     * @param digits 数字序列，如 "27" 对应 "ب ق" 等组合
     * @return 匹配的候选词列表（按词频/长度排序）
     */
    fun getCandidates(digits: String): List<String> {
        if (digits.isEmpty()) return emptyList()
        
        // 把每个数字转换成该键上的字母列表
        val lettersPerPosition = digits.mapNotNull { digit ->
            keyToLetters[digit]
        }
        
        if (lettersPerPosition.size != digits.length) return emptyList()
        
        // 匹配词典中长度相符的词
        val targetLength = digits.length
        val candidates = mutableListOf<String>()
        
        for (word in dictionary) {
            if (word.length == targetLength && matchesPattern(word, lettersPerPosition)) {
                candidates.add(word)
            }
        }
        
        // 按长度（短的先）和常用度排序
        return candidates.sortedBy { it.length }
    }

    /**
     * 检查单词是否匹配 T9 按键模式。
     */
    private fun matchesPattern(word: String, lettersPerPosition: List<List<Char>>): Boolean {
        for (i in word.indices) {
            val letter = word[i]
            val validLetters = lettersPerPosition[i]
            if (letter !in validLetters) {
                return false
            }
        }
        return true
    }

    /**
     * 获取数字键上的所有字母（用于 UI 显示）。
     */
    fun getKeyLetters(digit: Char): List<Char> = keyToLetters[digit] ?: emptyList()

    /**
     * 获取数字键上的第 n 个字母（用于循环输入）。
     */
    fun getLetterAt(digit: Char, index: Int): Char? {
        val letters = keyToLetters[digit] ?: return null
        return if (index in letters.indices) letters[index] else null
    }

    /**
     * 判断字符是否在某个数字键上。
     */
    fun getKeyForLetter(letter: Char): Char? {
        return keyToLetters.entries.find { letter in it.value }?.key
    }
}